require_once __DIR__.'/../includes/auth.php';requireAdmin();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=$_POST['action']??'add';if($action==='toggle'){$pdo->prepare('UPDATE coaches SET is_active=1-is_active WHERE id=?')->execute([(int)$_POST['id']]);}else{$name=trim((string)($_POST['name']??''));$spec=trim((string)($_POST['specialization']??''));$bio=trim((string)($_POST['bio']??''));$years=filter_var($_POST['experience_years']??'',FILTER_VALIDATE_INT);$fee=trim((string)($_POST['fee']??''));if($name===''||$spec==='')$error='Coach name and specialization are required.';else{$q=$pdo->prepare('INSERT INTO coaches(name,email,specialization,bio,experience_years,fee) VALUES(?,?,?,?,?,?)');$q->execute([$name,trim((string)($_POST['email']??''))?:null,$spec,$bio?:null,$years===false?null:$years,$fee===''?null:(float)$fee]);$coachId=(int)$pdo->lastInsertId();$weekday=(int)($_POST['weekday']??0);$from=$_POST['start_time']??'';$until=$_POST['end_time']??'';if($weekday>=1&&$weekday<=7&&$from!==''&&$until!==''&&$from<$until){$pdo->prepare('INSERT INTO coach_availability(coach_id,weekday,start_time,end_time) VALUES(?,?,?,?)')->execute([$coachId,$weekday,$from,$until]);}flash('Coach added. Add further weekly availability records if needed.');redirect('coaches.php');}}}
$rows=$pdo->query('SELECT c.*, (SELECT COUNT(*) FROM coach_availability a WHERE a.coach_id=c.id) availability_count FROM coaches c ORDER BY c.created_at DESC')->fetchAll();$pageTitle='Coach management';require __DIR__.'/../includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">COACH DIRECTORY</p><h1>Manage coaches</h1><p>Add coaches and control whether users can request sessions.</p></div></section><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="panel"><h2>Add coach</h2><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><div><label>Name</label><input name="name" required></div><div><label>Email (optional)</label><input type="email" name="email"></div><div><label>Specialization</label><input name="specialization" required></div><div><label>Experience (years)</label><input type="number" name="experience_years" min="0" max="60"></div><div><label>Fee (optional)</label><input type="number" step="0.01" min="0" name="fee"></div><div><label>First available weekday</label><select name="weekday"><option value="0">No schedule yet</option><option value="1">Monday</option><option value="2">Tuesday</option><option value="3">Wednesday</option><option value="4">Thursday</option><option value="5">Friday</option><option value="6">Saturday</option><option value="7">Sunday</option></select></div><div><label>Available from</label><input type="time" name="start_time"></div><div><label>Available until</label><input type="time" name="end_time"></div><div class="full"><label>Biography</label><textarea name="bio" rows="3"></textarea></div><div><button class="button">Add coach</button></div></form></section><section class="panel"><h2>Coach directory</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Specialization</th><th>Experience</th><th>Fee</th><th>Schedule slots</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['specialization'])?></td><td><?=e((string)($c['experience_years']??'—'))?></td><td><?=e((string)($c['fee']??'On request'))?></td><td><?=(int)$c['availability_count']?></td><td><?=$c['is_active']?'Active':'Inactive'?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><input type="hidden" name="action" value="toggle"><button class="button light btn-small">Toggle status</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
